CREATE TABLE IF NOT EXISTS "migrations" ("id" integer primary key autoincrement not null, "migration" varchar not null, "batch" integer not null);
CREATE TABLE sqlite_sequence(name,seq);
CREATE TABLE IF NOT EXISTS "organizations" ("id" integer primary key autoincrement not null, "name_ar" varchar not null, "name_en" varchar not null, "slug" varchar not null, "logo_url" varchar, "config" text, "is_active" tinyint(1) not null default '1', "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, "has_excellence_award" tinyint(1) not null default '0', "is_bit_khibra" tinyint(1) not null default '0', "has_iso_cert" tinyint(1) not null default '0');
CREATE UNIQUE INDEX "organizations_slug_unique" on "organizations" ("slug");
CREATE TABLE IF NOT EXISTS "users" ("id" integer primary key autoincrement not null, "organization_id" integer not null, "name" varchar not null, "email" varchar not null, "password" varchar not null, "role" varchar check ("role" in ('applicant', 'staff', 'auditor', 'admin', 'superuser')) not null default 'applicant', "phone" varchar, "is_active" tinyint(1) not null default '1', "must_change_password" tinyint(1) not null default '0', "password_changed_at" datetime, "email_verified_at" datetime, "remember_token" varchar, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, "annual_quota_m2" integer, "last_seen_at" datetime, "has_excellence_award" tinyint(1) not null default '0', "is_bit_khibra" tinyint(1) not null default '0', "has_iso_cert" tinyint(1) not null default '0', "office_classification" varchar, foreign key("organization_id") references "organizations"("id") on delete cascade);
CREATE UNIQUE INDEX "users_email_unique" on "users" ("email");
CREATE TABLE IF NOT EXISTS "personal_access_tokens" ("id" integer primary key autoincrement not null, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" varchar not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE INDEX "personal_access_tokens_tokenable_type_tokenable_id_index" on "personal_access_tokens" ("tokenable_type", "tokenable_id");
CREATE UNIQUE INDEX "personal_access_tokens_token_unique" on "personal_access_tokens" ("token");
CREATE TABLE IF NOT EXISTS "password_reset_tokens" ("email" varchar not null, "token" varchar not null, "created_at" datetime, primary key ("email"));
CREATE TABLE IF NOT EXISTS "service_definitions" ("id" integer primary key autoincrement not null, "organization_id" integer not null, "code" varchar not null, "name_ar" varchar not null, "name_en" varchar not null, "description_ar" varchar, "description_en" varchar, "currency" varchar not null default 'JOD', "schema" text not null, "status" varchar check ("status" in ('active', 'inactive', 'draft')) not null default 'draft', "created_at" datetime, "updated_at" datetime, "parent_code" varchar, "base_fee" numeric, "sla_hours" integer, "deleted_at" datetime, "phase" integer, "subcategory_ar" varchar, "subcategory_en" varchar, "is_locked" tinyint(1) not null default '1', foreign key("organization_id") references "organizations"("id") on delete cascade);
CREATE INDEX "service_definitions_organization_id_status_index" on "service_definitions" ("organization_id", "status");
CREATE UNIQUE INDEX "service_definitions_code_unique" on "service_definitions" ("code");
CREATE TABLE IF NOT EXISTS "application_documents" ("id" integer primary key autoincrement not null, "application_id" integer not null, "document_id" varchar not null, "original_filename" varchar not null, "stored_filename" varchar not null, "disk" varchar not null default 'local', "path" varchar not null, "mime_type" varchar not null, "size_bytes" integer not null, "uploaded_by" integer not null, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("application_id") references "applications"("id") on delete cascade, foreign key("uploaded_by") references "users"("id") on delete cascade);
CREATE INDEX "application_documents_application_id_document_id_index" on "application_documents" ("application_id", "document_id");
CREATE TABLE IF NOT EXISTS "application_reviews" ("id" integer primary key autoincrement not null, "application_id" integer not null, "reviewer_id" integer not null, "stage_id" varchar not null, "decision" varchar check ("decision" in ('approved', 'rejected', 'modifications_requested')) not null, "notes" text, "annotations" text, "review_round" integer not null default '1', "created_at" datetime, "updated_at" datetime, foreign key("application_id") references "applications"("id") on delete cascade, foreign key("reviewer_id") references "users"("id") on delete cascade);
CREATE INDEX "application_reviews_application_id_stage_id_index" on "application_reviews" ("application_id", "stage_id");
CREATE TABLE IF NOT EXISTS "certificates" ("id" integer primary key autoincrement not null, "application_id" integer not null, "organization_id" integer not null, "issued_to" integer not null, "issued_by" integer not null, "certificate_number" varchar not null, "qr_token" varchar not null, "status" varchar check ("status" in ('active', 'revoked', 'expired')) not null default 'active', "issued_date" date not null, "expiry_date" date not null, "cert_data" text, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("application_id") references "applications"("id") on delete cascade, foreign key("organization_id") references "organizations"("id") on delete cascade, foreign key("issued_to") references "users"("id") on delete cascade, foreign key("issued_by") references "users"("id") on delete cascade);
CREATE UNIQUE INDEX "certificates_application_id_unique" on "certificates" ("application_id");
CREATE UNIQUE INDEX "certificates_certificate_number_unique" on "certificates" ("certificate_number");
CREATE UNIQUE INDEX "certificates_qr_token_unique" on "certificates" ("qr_token");
CREATE TABLE IF NOT EXISTS "audit_logs" ("id" integer primary key autoincrement not null, "organization_id" integer not null, "user_id" integer, "auditable_type" varchar, "auditable_id" integer, "action" varchar not null, "rule_id" varchar, "from_status" varchar, "to_status" varchar, "input_snapshot" text, "extra" text, "is_manual_override" tinyint(1) not null default '0', "override_authorized_by" integer, "override_reason" text, "ip_address" varchar, "user_agent" varchar, "created_at" datetime not null default CURRENT_TIMESTAMP, foreign key("organization_id") references "organizations"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete set null, foreign key("override_authorized_by") references "users"("id") on delete set null);
CREATE INDEX "audit_logs_auditable_type_auditable_id_index" on "audit_logs" ("auditable_type", "auditable_id");
CREATE INDEX "audit_logs_organization_id_created_at_index" on "audit_logs" ("organization_id", "created_at");
CREATE INDEX "audit_logs_action_index" on "audit_logs" ("action");
CREATE TABLE IF NOT EXISTS "integration_cycles" ("id" integer primary key autoincrement not null, "cycle_ref" varchar not null, "service_name" varchar not null, "requirements_source" varchar not null default 'nashmi-requirement-ai', "requirements_file_path" varchar, "requirements_meta" text, "status" varchar not null default 'requirements_received', "nashmi_project_id" integer, "code_summary" text, "feedback" text, "notes" text, "requirements_received_at" datetime, "code_done_notified_at" datetime, "feedback_received_at" datetime, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime);
CREATE UNIQUE INDEX "integration_cycles_cycle_ref_unique" on "integration_cycles" ("cycle_ref");
CREATE INDEX "integration_cycles_status_index" on "integration_cycles" ("status");
CREATE TABLE IF NOT EXISTS "gsb_call_logs" ("id" integer primary key autoincrement not null, "gsb_endpoint" varchar not null, "http_method" varchar not null, "source_ip" varchar not null, "user_identifier" varchar, "user_id" integer, "service_name" varchar, "operation" varchar, "is_citizen_data" tinyint(1) not null default '0', "otp_verified" tinyint(1) not null default '0', "response_status" integer, "success" tinyint(1) not null default '0', "error_code" text, "ip_whitelisted" tinyint(1) not null default '1', "bulk_request" tinyint(1) not null default '0', "committee_approved" tinyint(1), "duration_ms" integer, "logged_at" datetime not null, "created_at" datetime, "updated_at" datetime);
CREATE INDEX "gsb_call_logs_logged_at_index" on "gsb_call_logs" ("logged_at");
CREATE INDEX "gsb_call_logs_user_id_index" on "gsb_call_logs" ("user_id");
CREATE INDEX "gsb_call_logs_source_ip_index" on "gsb_call_logs" ("source_ip");
CREATE INDEX "gsb_call_logs_gsb_endpoint_index" on "gsb_call_logs" ("gsb_endpoint");
CREATE INDEX "gsb_call_logs_success_index" on "gsb_call_logs" ("success");
CREATE INDEX "gsb_call_logs_is_citizen_data_logged_at_index" on "gsb_call_logs" ("is_citizen_data", "logged_at");
CREATE INDEX "service_definitions_organization_id_parent_code_index" on "service_definitions" ("organization_id", "parent_code");
CREATE TABLE IF NOT EXISTS "engineers" ("id" integer primary key autoincrement not null, "organization_id" integer not null, "office_user_id" integer not null, "name_ar" varchar not null, "name_en" varchar, "membership_number" varchar not null, "specialization" varchar, "phone" varchar, "email" varchar, "annual_quota_m2" integer, "is_active" tinyint(1) not null default '1', "deleted_at" datetime, "created_at" datetime, "updated_at" datetime, "is_specialization_head" tinyint(1) not null default '0', foreign key("organization_id") references "organizations"("id") on delete cascade, foreign key("office_user_id") references "users"("id") on delete cascade);
CREATE UNIQUE INDEX "engineers_office_user_id_membership_number_unique" on "engineers" ("office_user_id", "membership_number");
CREATE INDEX "engineers_office_user_id_is_active_index" on "engineers" ("office_user_id", "is_active");
CREATE INDEX "engineers_organization_id_index" on "engineers" ("organization_id");
CREATE TABLE IF NOT EXISTS "projects" ("id" integer primary key autoincrement not null, "organization_id" integer not null, "owner_user_id" integer not null, "name_ar" varchar not null, "name_en" varchar, "type" varchar, "area_m2" integer, "city" varchar, "contract_no" varchar, "request_no" varchar, "status" varchar not null default ('pending'), "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, "engineer_id" integer, foreign key("owner_user_id") references users("id") on delete cascade on update no action, foreign key("organization_id") references organizations("id") on delete cascade on update no action, foreign key("engineer_id") references "engineers"("id") on delete set null);
CREATE INDEX "projects_organization_id_owner_user_id_index" on "projects" ("organization_id", "owner_user_id");
CREATE INDEX "projects_engineer_id_index" on "projects" ("engineer_id");
