CREATE INDEX "service_definitions_organization_id_parent_code_subcategory_ar_index" on "service_definitions" ("organization_id", "parent_code", "subcategory_ar");
CREATE TABLE IF NOT EXISTS "applications" ("id" integer primary key autoincrement not null, "reference_number" varchar not null, "organization_id" integer not null, "service_definition_id" integer not null, "applicant_id" integer not null, "assigned_reviewer_id" integer, "status" varchar not null default ('draft'), "current_stage" varchar, "data" text, "fee_amount" numeric not null default ('0'), "payment_status" varchar not null default ('pending'), "payment_reference" varchar, "payment_confirmed_at" datetime, "sla_deadline" datetime, "sla_breached_at" datetime, "review_round" integer not null default ('0'), "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, "project_id" integer, "contract_no" varchar, foreign key("assigned_reviewer_id") references users("id") on delete set null on update no action, foreign key("applicant_id") references users("id") on delete cascade on update no action, foreign key("service_definition_id") references service_definitions("id") on delete cascade on update no action, foreign key("organization_id") references organizations("id") on delete cascade on update no action, foreign key("project_id") references "projects"("id") on delete set null);
CREATE INDEX "applications_applicant_id_status_index" on "applications" ("applicant_id", "status");
CREATE INDEX "applications_assigned_reviewer_id_index" on "applications" ("assigned_reviewer_id");
CREATE INDEX "applications_organization_id_status_index" on "applications" ("organization_id", "status");
CREATE UNIQUE INDEX "applications_reference_number_unique" on "applications" ("reference_number");
